package net.reqnroll.idesupport.rider.telemetry

/**
 * Built-in Application Insights resources (issue #1160): one per environment. The build picks one
 * via [TelemetryBuildConfig.ENVIRONMENT] (generated by the `generateTelemetryBuildConfig` Gradle task
 * from `-PtelemetryEnv` / `REQNROLL_TELEMETRY_ENV`): `prod` for release builds, `dev` (the default)
 * for everything else. VS and VS Code carry the same pair:
 *  - VS: `src/VisualStudio/Reqnroll.IdeSupport.VisualStudio.VSSDKIntegration/Telemetry/InstrumentationKey.{Dev,Prod}.txt`
 *  - VS Code: `src/VSCode/src/telemetryConnections.ts`
 *
 * Connection strings are not secrets (they ship inside every client), so they are committed. The
 * `generateTelemetryBuildConfig` task refuses a `prod` build while any PROD value still contains `TODO`.
 */
internal object TelemetryConnections {
    // TODO(#1160): paste the real values (reqnroll-ide-appinsights-dev / -prod). The endpoint is the
    // connection string's IngestionEndpoint with /v2/track appended.
    const val DEV_INSTRUMENTATION_KEY = "00000000-0000-0000-0000-000000000000"
    const val DEV_INGESTION_ENDPOINT = "https://TODO-region.in.applicationinsights.azure.com/v2/track"
    const val PROD_INSTRUMENTATION_KEY = "00000000-0000-0000-0000-000000000000"
    const val PROD_INGESTION_ENDPOINT = "https://TODO-region.in.applicationinsights.azure.com/v2/track"

    fun instrumentationKey(environment: String): String =
        if (environment == "prod") PROD_INSTRUMENTATION_KEY else DEV_INSTRUMENTATION_KEY

    fun ingestionEndpoint(environment: String): String =
        if (environment == "prod") PROD_INGESTION_ENDPOINT else DEV_INGESTION_ENDPOINT
}
